val Char.isNewline: Boolean inline get() = when (this) {
    '\n', '\r', '\u000B', '\u000C', '\u0085', '\u2028', '\u2029' -> true
    else -> false
}

val String.newlines: Int get() {
    var idx = 0
    var count = 0

    while (idx < length) {
        val curr = get(idx)
        val next = getOrNull(idx + 1)

        idx += when {
            curr == '\r' && next == '\n' -> {
                count += 1

                2
            }

            curr.isNewline -> {
                count += 1

                1
            }

            else -> 1
        }
    }

    return count
}

internal val KordNode?.length: Int inline get() = this?.length ?: 0
internal val KordNode?.newlines: Int inline get() = this?.newlines ?: 0

internal class KordNode(
    val contents: String,

    /** Random Priority for balancing */
    val prio: Int,
    val chunkNewlines: Int = contents.newlines,

    val left: KordNode? = null,
    val right: KordNode? = null,
) {
    init {
        // Runs before the property initializers below, which rely on non-empty contents.
        check(contents.isNotEmpty()) { "KordNode chunks must not be empty" }
    }

    /** Length of entire tree */
    val length = left.length + right.length + contents.length

    val firstChar: Char = left?.firstChar ?: contents.first()
    val lastChar: Char = right?.lastChar ?: contents.last()

    /** Count of newlines in entire tree */
    val newlines = calculateNewlines()

    fun calculateNewlines(): Int {
        var newlines = left.newlines + right.newlines + chunkNewlines

        // Correct for split newlines
        if (left?.lastChar == '\r' && contents.first() == '\n') {
            newlines -= 1
        }

        // Correct for split newlines
        if (right?.firstChar == '\n' && contents.last() == '\r') {
            newlines -= 1
        }

        return newlines
    }

    companion object {
        fun merge(left: KordNode?, right: KordNode?): KordNode? {
            return when {
                left == null -> right
                right == null -> left

                left.prio >= right.prio -> left.with(left.left, merge(left.right, right))
                else                    -> right.with(merge(left, right.left), right.right)
            }
        }
    }

    fun with(left: KordNode? = this.left, right: KordNode? = this.right) = KordNode(
        contents,
        prio,
        chunkNewlines,
        left,
        right,
    )

    fun split(at: Int): Pair<KordNode?, KordNode?> {
        val startIndex: Int = left?.length ?: 0
        val endIndex: Int = startIndex + contents.length

        return when {
            at == startIndex -> when {
                left?.lastChar == '\r' && contents.first() == '\n' -> split(at - 1)
                else -> left to with(left = null)
            }

            at == endIndex -> when {
                right?.firstChar == '\n' && contents.last() == '\r' -> split(at - 1)
                else -> with(right = null) to right
            }

            at < startIndex -> {
                // Split in left subtree
                val (ll, lr) = left?.split(at) ?: (null to null)

                ll to with(lr, right)
            }

            at > endIndex -> {
                // Split in right subtree
                val (rl, rr) = right?.split(at - endIndex) ?: (null to null)

                with(left, rl) to rr
            }

            else -> {
                // Split in this node
                var splitPoint = at - startIndex

                // Nudge split point to before newline if user attempts to edit in the middle of one.
                if (contents[splitPoint] == '\n' && splitPoint >= 1 && contents[splitPoint - 1] == '\r') {
                    splitPoint -= 1
                }

                val cl = contents.substring(0, splitPoint)
                val cr = contents.substring(splitPoint)

                when {
                    cl.isEmpty() -> left to with(left = null)

                    else -> KordNode(
                        contents = cl,
                        prio = prio,
                        left = left,
                        right = null,
                    ) to KordNode(
                        contents = cr,
                        prio = prio,
                        left = null,
                        right = right,
                    )
                }
            }
        }
    }
}

sealed interface Kord {

}

/**
 * Rope Data Structure.
 */
internal class KordImpl internal constructor(
    private val root: KordNode? = null,
    private val randomProvider: () -> Int,
): Kord {
    val length: Int
        get() = root.length

    private fun checkIndexing(at: Int) {
        if (at < 0 || at > root.length) throw IndexOutOfBoundsException("Kord is ${root.length} bytes long, cannot index at $at")
    }

    fun insert(at: Int, contents: String): KordImpl {
        checkIndexing(at)

        if (contents.isEmpty()) return this

        val node = KordNode(contents, randomProvider())
        val (left, right) = root?.split(at) ?: return KordImpl(node, randomProvider)

        val merged = KordNode.merge(
            KordNode.merge(
                left,
                node,
            ),
            right,
        )

        return KordImpl(merged, randomProvider)
    }

    fun split(at: Int): Pair<KordImpl, KordImpl> {
        checkIndexing(at)

        val (lhs, rhs) = root?.split(at) ?: return Pair(this, this)

        return Pair(
            KordImpl(lhs, randomProvider),
            KordImpl(rhs, randomProvider),
        )
    }
}

fun Kord(vararg of: String): Kord {
    val seededRandom = Random(Random.nextLong())

    return of.fold(KordImpl { seededRandom.nextInt() }) { impl, item -> impl.insert(impl.length, item) }
}
